  'mirror: { btn: "#settle-appeals-action-mirror", target: "reverse-stairwell"',
  'gavel: { btn: "#settle-appeals-action-gavel", target: "return-audit"',
  'bell: { btn: "#settle-appeals-action-bell", target: "bellless-ward"',
