  assert.strictEqual(ctx.v74.tombstonePatentOfficeUnlocked(), false, "v74 locked when v73 locked");
  assert.strictEqual(ctx.v74.tombstonePatentOfficeCanVisitOffice(), false, "locked office guard blocks");
